const NarrativeManager = {
    init: function () {
        if (!gameState.narrative) {
            gameState.narrative = {
                history: [],
                lastAmbientWhisper: {},
                flags: []
            };
        }

        // Hook into Level Up
        this.hookLevelUp();

        console.log("📖 NarrativeManager Initialized");
    },

    hookLevelUp: function () {
        // Safe wrapping of global functions
        if (typeof window.checkLevelUp === 'function' && !window.checkLevelUp._hooked) {
            const originalCheckLevelUp = window.checkLevelUp;
            window.checkLevelUp = function () {
                const oldLevel = gameState.level;
                originalCheckLevelUp();
                if (gameState.level > oldLevel) {
                    NarrativeManager.handleLevelUp(gameState.level);
                }
            };
            window.checkLevelUp._hooked = true;
            console.log("✅ checkLevelUp hooked for Narrative");
        } else {
            // Retry later if function not yet defined
            setTimeout(() => this.hookLevelUp(), 1000);
        }
    },

    handleLevelUp: function (level) {
        console.log(`🆙 Level Up detected: ${level}`);

        // Check for specific narrative event
        if (LEVEL_UP_NARRATIVE[level]) {
            const eventId = LEVEL_UP_NARRATIVE[level];
            this.triggerEvent(eventId);
        }

        // Trigger ambient whisper
        triggerAmbientNarrative('level_up', { level: level });
    },

    triggerEvent: function (eventId) {
        // Prevent duplicate events
        if (gameState.narrative.history.includes(eventId)) return;

        const event = NARRATIVE_EVENTS[eventId];
        if (event) {
            // Use existing Porygon system if available, else fallback
            if (typeof window.showPorygonMessage === 'function') {
                // Convert lines to Porygon format if needed or specific function
                // For now, we simulate a custom message
                // We map to showPorygonMessage mood logic
                window.showPorygonMessage(event.mood, event.lines); // Hypothetical signature
            } else {
                // Fallback to modal
                this.showModalDialogue(event.lines);
            }

            gameState.narrative.history.push(eventId);
            saveGame();
        } else if (PORYGON_DIALOGUES[eventId]) {
            // It's a key in the existing dialogues
            if (typeof triggerNarrative === 'function') {
                triggerNarrative(eventId);
            }
        }
    },

    showModalDialogue: function (lines) {
        // Fallback implementation
        const text = lines.join('<br><br>');
        const modal = document.createElement('div');
        modal.className = 'modal active';
        modal.style.cssText = 'display:flex;justify-content:center;align-items:center;position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.9);z-index:99999;';
        modal.innerHTML = `
            <div style="background:#000;border:2px solid #0f0;padding:20px;max-width:600px;color:#0f0;font-family:'Courier New';box-shadow:0 0 15px #0f0;">
                <h3>> INCOMING_TRANSMISSION</h3>
                <p>${text}</p>
                <button onclick="this.closest('.modal').remove()" style="background:#0f0;color:#000;border:none;padding:10px 20px;margin-top:20px;cursor:pointer;font-weight:bold;">ACKNOWLEDGE</button>
            </div>
         `;
        document.body.appendChild(modal);
    }
};

// Auto-init on load
window.addEventListener('load', () => {
    setTimeout(() => NarrativeManager.init(), 2000); // Wait for other systems
});

// Fonction pour déclencher un murmure d'entropie (non bloquant)
function triggerAmbientNarrative(context, variables = {}) {
    // Sécurité : si gameState n'est pas prêt
    if (!gameState || !gameState.narrative) return;

    // Initialisation
    if (!gameState.narrative.lastAmbientWhisper) gameState.narrative.lastAmbientWhisper = {};

    const whispers = PORYGON_DIALOGUES[context] || PORYGON_DIALOGUES['entropy_high']; // Fallback
    if (!whispers || !Array.isArray(whispers)) return;

    // Probabilité de déclenchement (1-5% selon le contexte)
    // Légendaire/Shiny = plus fréquent (20%), Standard = rare (2%)
    let chance = 0.02;
    if (context.includes('legendary') || context.includes('shiny') || context.includes('glitch')) chance = 0.20;

    if (Math.random() > chance) return;

    // Cooldown de 1 minute par type de contexte
    const lastWhisperTime = gameState.narrative.lastAmbientWhisper[context] || 0;
    const now = Date.now();
    if (now - lastWhisperTime < 60000) return;

    // Sélection aléatoire
    const whisper = whispers[Math.floor(Math.random() * whispers.length)];
    let message = whisper;

    // Remplacer les variables {var}
    Object.keys(variables).forEach(key => {
        message = message.replace(`{${key}}`, variables[key]);
    });

    // Affichage style "Terminal"
    showAmbientWhisper(message);

    // Mise à jour du timestamp
    gameState.narrative.lastAmbientWhisper[context] = now;
}

// Affichage visuel du murmure (Style Terminal Vert)
function showAmbientWhisper(message) {
    let container = document.getElementById('entropy-whisper-container');
    if (!container) {
        container = document.createElement('div');
        container.id = 'entropy-whisper-container';
        container.style.cssText = `
            position: fixed;
            bottom: 120px;
            right: 20px;
            width: 300px;
            display: flex;
            flex-direction: column;
            align-items: flex-end;
            gap: 10px;
            pointer-events: none;
            z-index: 9999;
        `;
        document.body.appendChild(container);
    }

    const toast = document.createElement('div');
    toast.style.cssText = `
        background: rgba(0, 20, 0, 0.85);
        color: #00ff00;
        font-family: 'Courier New', monospace;
        padding: 10px 15px;
        border-left: 3px solid #00ff00;
        border-radius: 4px;
        font-size: 0.9em;
        text-shadow: 0 0 5px rgba(0, 255, 0, 0.5);
        opacity: 0;
        transform: translateX(20px);
        transition: all 0.5s ease;
        box-shadow: 0 0 10px rgba(0, 0, 0, 0.5);
        max-width: 100%;
    `;
    toast.innerHTML = `> ${message}<span class="blink">_</span>`;

    container.appendChild(toast);

    // Animation d'entrée
    requestAnimationFrame(() => {
        toast.style.opacity = '1';
        toast.style.transform = 'translateX(0)';
    });

    // Disparition auto
    setTimeout(() => {
        toast.style.opacity = '0';
        toast.style.transform = 'translateX(20px)';
        setTimeout(() => toast.remove(), 500);
    }, 6000);
}

