// Fonction pour rendre la page Poké-Poker
function renderPokerPage() {
    const run = gameState.poker.current_run;
    const bottomNav = document.querySelector('.bottom-nav');

    // Récupérer les éléments avec vérification d'existence
    const startScreen = document.getElementById('poker-start-screen');
    const runScreen = document.getElementById('poker-run-screen');
    const lobbyScreen = document.getElementById('poker-lobby-screen');

    // Si les éléments n'existent pas, le jeu React n'est peut-être pas encore chargé
    // Dans ce cas, on ne fait rien et on laisse React gérer l'affichage
    if (!startScreen || !runScreen || !lobbyScreen) {
        // Le jeu Poké-Poker utilise React et sera rendu par le composant React
        // On ne fait rien ici pour éviter les erreurs
        return;
    }

    if (!run || !run.active) {
        // Afficher écran de démarrage (première page)
        startScreen.style.display = 'block';
        runScreen.style.display = 'none';
        lobbyScreen.style.display = 'none';
        // Réafficher les barres de menu
        if (bottomNav) bottomNav.style.display = 'flex';
        renderPokerGlobalStats();
    } else {
        // Vérifier si on est en mode Lobby (entre blinds) ou en mode Play
        const isInPlayMode = run.current_blind && run.blind_in_progress;

        if (isInPlayMode) {
            // Afficher écran de jeu (Main Play)
            startScreen.style.display = 'none';
            lobbyScreen.style.display = 'none';
            runScreen.style.display = 'block';
            // Cacher les barres de menu pendant la partie
            if (bottomNav) bottomNav.style.display = 'none';
            renderPokerRunScreen();
        } else {
            // Afficher Run Lobby avec les 3 Blinds
            startScreen.style.display = 'none';
            runScreen.style.display = 'none';
            lobbyScreen.style.display = 'block';
            // Réafficher les barres de menu dans le lobby
            if (bottomNav) bottomNav.style.display = 'flex';
            renderPokerRunLobby();
        }
    }
}

