// Fonction pour mettre à jour la jauge de Stabilité Système (Niveaux 1-2)
function updateSystemStabilityDisplay() {
    const stabilityDisplay = document.getElementById('system-stability-display');
    const stabilityBar = document.getElementById('stability-bar-fill');
    const stabilityText = document.getElementById('stability-text');

    if (!stabilityDisplay || !stabilityBar || !stabilityText) return;

    const TARGET_CAPTURES = 3;
    const currentCaptures = gameState.totalCaught || 0;
    const isCompleted = currentCaptures >= TARGET_CAPTURES;
    const alreadyTriggered = (gameState.system?.narrativeFlags || []).includes('system_stabilizing_5_shown');

    // Masquer si la complétion a déjà été traitée (le timeout de 3s s'en charge)
    if (isCompleted && alreadyTriggered) {
        stabilityDisplay.style.display = 'none';
        return;
    }

    // Masquer si niveau > 2 sans complétion en attente
    if (gameState.level > 2 && !isCompleted) {
        stabilityDisplay.style.display = 'none';
        return;
    }

    stabilityDisplay.style.display = 'flex';

    const stabilityPercent = Math.min((currentCaptures / TARGET_CAPTURES) * 100, 100);

    // Mettre à jour la barre
    stabilityBar.style.width = `${stabilityPercent}%`;

    // Texte contextuel
    if (currentCaptures === 0) {
        stabilityText.textContent = '0% — Démarrage...';
    } else if (!isCompleted) {
        const remaining = TARGET_CAPTURES - currentCaptures;
        stabilityText.textContent = `${Math.round(stabilityPercent)}% — ${remaining} capture${remaining > 1 ? 's' : ''} restante${remaining > 1 ? 's' : ''}`;
    } else {
        stabilityText.textContent = '100% — Système stable';
    }

    // Couleur selon progression
    if (stabilityPercent < 34) {
        stabilityBar.style.background = 'linear-gradient(90deg, #ef4444, #f59e0b)';
    } else if (stabilityPercent < 67) {
        stabilityBar.style.background = 'linear-gradient(90deg, #f59e0b, #eab308)';
    } else {
        stabilityBar.style.background = 'linear-gradient(90deg, #eab308, #10b981)';
    }

    // Déclencher la complétion une seule fois dès que la cible est atteinte
    if (isCompleted && !alreadyTriggered) {
        if (!gameState.system) gameState.system = {};
        if (!gameState.system.narrativeFlags) gameState.system.narrativeFlags = [];
        gameState.system.narrativeFlags.push('system_stabilizing_5_shown');

        setTimeout(() => {
            if (typeof triggerNarrative === 'function') triggerNarrative('system_stabilizing');
        }, 1500);

        if (typeof updateSystemVisualState === 'function') updateSystemVisualState();

        // Masquer après 3s pour laisser voir "100% — Système stable"
        setTimeout(() => {
            if (stabilityDisplay) stabilityDisplay.style.display = 'none';
        }, 3000);
    }
}

// Fonction pour masquer/afficher l'item Quêtes dans le Hub selon le niveau
function updateQuestsVisibility() {
    // Initialiser le module quêtes si absent
    if (!gameState.modules) gameState.modules = {};
    if (!gameState.modules.quests) {
        gameState.modules.quests = {
            id: 'quests',
            condition: 'level_3',
            unlocked: gameState.level >= 3
        };
    }

    const questsItem = document.querySelector('.hub-item.quests');
    if (!questsItem) return;

    const isUnlocked = gameState.modules.quests.unlocked || gameState.level >= 3;

    if (!isUnlocked) {
        // Masquer avec style narratif (perte de mémoire)
        questsItem.style.position = 'relative';
        questsItem.style.opacity = '0.3';
        questsItem.style.filter = 'grayscale(100%) blur(2px)';
        questsItem.style.pointerEvents = 'none';
        questsItem.style.cursor = 'not-allowed';

        // Ajouter un overlay narratif
        let overlay = questsItem.querySelector('.quests-locked-overlay');
        if (!overlay) {
            overlay = document.createElement('div');
            overlay.className = 'quests-locked-overlay';
            overlay.style.cssText = `
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                background: rgba(0, 0, 0, 0.7);
                border-radius: 16px;
                display: flex;
                flex-direction: column;
                align-items: center;
                justify-content: center;
                z-index: 10;
                backdrop-filter: blur(5px);
            `;
            questsItem.appendChild(overlay);
        }

        // Icône de processeur/électricité + cadenas avec niveau
        overlay.innerHTML = `
            <div style="font-size: 1.5em; margin-bottom: 5px; filter: drop-shadow(0 0 5px rgba(255, 0, 0, 0.5));">⚡</div>
            <div style="font-size: 1.2em; margin-bottom: 3px;">🔒</div>
            <div style="font-size: 0.7em; color: rgba(255, 255, 255, 0.8); font-family: var(--font-family-pixel); text-align: center;">
                LVL 3
            </div>
            <div style="font-size: 0.6em; color: rgba(255, 255, 255, 0.6); margin-top: 2px; text-align: center; font-family: var(--font-family-pixel);">
                MÉMOIRE CORROMPUE
            </div>
        `;
    } else {
        // Afficher normalement
        questsItem.style.opacity = '1';
        questsItem.style.filter = 'none';
        questsItem.style.pointerEvents = 'auto';
        questsItem.style.cursor = 'pointer';

        // Supprimer l'overlay si présent
        const overlay = questsItem.querySelector('.quests-locked-overlay');
        if (overlay) overlay.remove();

        // Ajouter une notification "Nouveau !" si c'est la première fois qu'on débloque
        if (!gameState.system.narrativeFlags.includes('quests_unlocked_shown')) {
            gameState.system.narrativeFlags.push('quests_unlocked_shown');
            const notifBadge = document.getElementById('hub-notif-quests');
            if (notifBadge) {
                notifBadge.style.display = 'block';
                notifBadge.style.background = '#10b981';
                notifBadge.style.width = '24px';
                notifBadge.style.height = '24px';
                notifBadge.style.fontSize = '0.8em';
                notifBadge.textContent = 'N';
                // Animation pulse pour attirer l'attention
                notifBadge.style.animation = 'pulse 1.5s ease-in-out infinite';
            }
        }
    }
}

function updateQuestProgress(type, value) { if (type === 'captures') { for (const quest of QUESTS_DATA.daily) { if (quest.trackType === 'captures') gameState.questsProgress.daily[quest.id] = (gameState.questsProgress.daily[quest.id] || 0) + value; } gameState.questsProgress.special['special_mystery_egg'] = (gameState.questsProgress.special['special_mystery_egg'] || 0) + value; gameState.questsProgress.special['special_complete_kanto'] = gameState.captured.size; gameState.questsProgress.permanent['perm_hundred_captures'] = gameState.totalCaught; gameState.questsProgress.permanent['perm_thousand_captures'] = gameState.totalCaught; if (!gameState.mysteryEggProgress) gameState.mysteryEggProgress = 0; gameState.mysteryEggProgress += value; if (gameState.inventory.eggs) { gameState.inventory.eggs.forEach(egg => { if (egg.id === 'mystery_egg' && egg.state === 'locked') { egg.progress = (egg.progress || 0) + value; if (egg.progress >= 50) { egg.state = 'ready'; } } }) } } if (type === 'shinies') { for (const quest of QUESTS_DATA.daily) { if (quest.trackType === 'shinies') gameState.questsProgress.daily[quest.id] = (gameState.questsProgress.daily[quest.id] || 0) + value; } gameState.questsProgress.special['special_10_shinies'] = gameState.shinies.size; } if (type === 'legendaries') { for (const quest of QUESTS_DATA.daily) { if (quest.trackType === 'legendaries') gameState.questsProgress.daily[quest.id] = (gameState.questsProgress.daily[quest.id] || 0) + value; } gameState.questsProgress.special['special_3_legendaries'] = (gameState.questsProgress.special['special_3_legendaries'] || 0) + value; gameState.questsProgress.permanent['perm_legendary_5'] = (gameState.questsProgress.permanent['perm_legendary_5'] || 0) + value; } if (type === 'flees') { for (const quest of QUESTS_DATA.daily) { if (quest.trackType === 'flees') gameState.questsProgress.daily[quest.id] = (gameState.questsProgress.daily[quest.id] || 0) + value; } } if (type === 'fished') { for (const quest of QUESTS_DATA.daily) { if (quest.trackType === 'fished') gameState.questsProgress.daily[quest.id] = (gameState.questsProgress.daily[quest.id] || 0) + value; } } if (type === 'coins') { for (const quest of QUESTS_DATA.daily) { if (quest.trackType === 'coins') gameState.questsProgress.daily[quest.id] = (gameState.questsProgress.daily[quest.id] || 0) + value; } } if (type === 'streak') { for (const quest of QUESTS_DATA.daily) { if (quest.trackType === 'streak') gameState.questsProgress.daily[quest.id] = Math.max(gameState.questsProgress.daily[quest.id] || 0, value); } gameState.questsProgress.permanent['perm_streak_50'] = Math.max(gameState.questsProgress.permanent['perm_streak_50'] || 0, value); } if (type === 'rare_captures') { for (const quest of QUESTS_DATA.daily) { if (quest.trackType === 'rare_captures') gameState.questsProgress.daily[quest.id] = (gameState.questsProgress.daily[quest.id] || 0) + value; } } if (type.startsWith('type_master_')) { const maxTypeCount = Math.max(...Object.values(gameState.typeCaptureCounts || {}), 0); gameState.questsProgress.permanent['perm_type_master'] = maxTypeCount; } if (type.startsWith('regional_')) { const region = type.replace('regional_', ''); const maxRegionCount = Math.max(...Object.values(gameState.regionProgress || {}).map(r => r.captured || 0), 0); gameState.questsProgress.permanent['perm_regional_collection'] = maxRegionCount; } if (type === 'shop_purchases') { gameState.questsProgress.permanent['perm_lucky_merchant'] = value; } if (type === 'login_streak') { gameState.questsProgress.permanent['perm_perfect_routine'] = value; } if (type === 'blindbox_opened') { gameState.questsProgress.permanent['perm_hidden_treasure'] = value; } if (type === 'rogue_completed') { for (const quest of QUESTS_DATA.daily) { if (quest.trackType === 'rogue_completed') gameState.questsProgress.daily[quest.id] = (gameState.questsProgress.daily[quest.id] || 0) + value; } gameState.questsProgress.permanent['perm_rogue_master'] = (gameState.questsProgress.permanent['perm_rogue_master'] || 0) + value; } if (type === 'rogue_full_clear') { gameState.questsProgress.special['special_rogue_10'] = (gameState.questsProgress.special['special_rogue_10'] || 0) + value; } checkQuestNotifications(); }

function checkQuestNotifications() {
    let hasNewCompletions = false;
    for (const questType of ['daily', 'special', 'permanent']) {
        const questsArray = QUESTS_DATA[questType];
        for (const quest of questsArray) {
            const progress = gameState.questsProgress[questType][quest.id] || 0;
            // Si quête terminée mais pas encore réclamée
            if (progress >= quest.target && !gameState.claimedQuests[questType].has(quest.id)) {
                hasNewCompletions = true;
                break;
            }
        }
        if (hasNewCompletions) break;
    }

    // Cible le nouveau badge dans le Hub
    const hubBadge = document.getElementById('hub-notif-quests');
    // Cible aussi le badge de la barre de nav si tu l'as laissé (optionnel)
    const oldBadge = document.getElementById('quest-notif-badge');

    if (hubBadge) hubBadge.style.display = hasNewCompletions ? 'block' : 'none';
    if (oldBadge) oldBadge.style.display = hasNewCompletions ? 'flex' : 'none';
}

// ===== PART 2: CAPTURE & PÊCHE & POKÉDEX =====

window.spawnPokemon = function () {
    if (captureCooldown) { const remaining = Math.ceil((captureCooldown - Date.now()) / 1000); showToast(`Attendez ${remaining}s avant de respawn`, 'error'); return; } currentPokemon = selectPokemon('spawn', false); usingFramby = false; usingPinap = false; usingCeriz = false; const encounterDiv = document.getElementById('encounter'); if (!encounterDiv) return; init3DPokeball('encounter', 'Un Pokémon apparaît...'); setTimeout(() => revealPokemon(), 800);
    // ===== DÉCLENCHEUR D'OMBRE DE GLITCH =====
    setTimeout(() => {
        if (typeof triggerGlitchShadow === 'function') {
            triggerGlitchShadow();
        }
    }, 1000);
};

function revealPokemon() { const encounterDiv = document.getElementById('encounter'); if (!encounterDiv || !currentPokemon) return; const isNew = !gameState.captured.has(currentPokemon.id); const statusBadge = isNew ? '<div style="background: #10b981; color: white; padding: 5px 15px; border-radius: 15px; display: inline-block; margin-bottom: 10px; font-size: 0.9em;">✨ NOUVEAU!</div>' : '<div style="background: #f59e0b; color: white; padding: 5px 15px; border-radius: 15px; display: inline-block; margin-bottom: 10px; font-size: 0.9em;">📖 Doublon</div>'; let berriesHTML = ''; if (gameState.inventory.framby > 0) berriesHTML += `<div style="margin-bottom: 10px;"><label style="color: white; cursor: pointer; background: rgba(255,255,255,0.1); padding: 10px 20px; border-radius: 10px; display: inline-block;"><input type="checkbox" onchange="usingFramby = this.checked; revealPokemon();" ${usingFramby ? 'checked' : ''} style="margin-right: 8px;">${getItemIconDisplay('framby', '1.2em')} Baie Framby (+50%) [${gameState.inventory.framby}]</label></div>`; if (gameState.inventory.pinap > 0) berriesHTML += `<div style="margin-bottom: 10px;"><label style="color: white; cursor: pointer; background: rgba(255,255,255,0.1); padding: 10px 20px; border-radius: 10px; display: inline-block;"><input type="checkbox" onchange="usingPinap = this.checked; revealPokemon();" ${usingPinap ? 'checked' : ''} style="margin-right: 8px;">${getItemIconDisplay('pinap', '1.2em')} Baie Pinap (×2 coins) [${gameState.inventory.pinap}]</label></div>`; if (gameState.inventory.ceriz > 0 && currentPokemon.isShiny) berriesHTML += `<div style="margin-bottom: 10px;"><label style="color: #FFD700; cursor: pointer; background: rgba(255, 215, 0, 0.2); padding: 10px 20px; border-radius: 10px; display: inline-block;"><input type="checkbox" onchange="usingCeriz = this.checked; revealPokemon();" ${usingCeriz ? 'checked' : ''} style="margin-right: 8px;">${getItemIconDisplay('ceriz', '1.2em')} Baie Ceriz (100% SHINY!) [${gameState.inventory.ceriz}]</label></div>`; encounterDiv.innerHTML = `<div style="text-align: center; padding: 30px; background: linear-gradient(180deg, rgba(102, 126, 234, 0.3), rgba(118, 75, 162, 0.3)); border-radius: 15px;">${statusBadge}<div style="font-size: 1.3em; font-weight: bold; margin-bottom: 15px; color: white;">${currentPokemon.rarity === 'legendary' ? '⚡ POKÉMON LÉGENDAIRE ⚡' : currentPokemon.rarity === 'super_rare' ? '💎 SUPER RARE 💎' : currentPokemon.rarity === 'rare' ? '⭐ RARE ⭐' : currentPokemon.rarity === 'uncommon' ? '🔵 PEU COMMUN 🔵' : '⚪ COMMUN ⚪'}</div><div style="background: rgba(255,255,255,0.1); padding: 20px; border-radius: 15px; margin-bottom: 15px;"><img src="${getAnimatedSpriteUrl(currentPokemon.id, currentPokemon.isShiny)}" style="width: 150px; height: 150px; min-width: 150px; min-height: 150px; max-width: 150px; max-height: 150px; image-rendering: pixelated; ${currentPokemon.isShiny ? 'filter: drop-shadow(0 0 20px #FFD700);' : ''}; object-fit: contain; object-position: center; display: block; margin: 0 auto;" alt="${currentPokemon.name}"></div><div style="font-size: 1.5em; font-weight: bold; margin: 10px 0; color: ${currentPokemon.isShiny ? '#FFD700' : 'white'};"> ${currentPokemon.isShiny ? '✨ ' : ''}${currentPokemon.name}${currentPokemon.isShiny ? ' ✨' : ''}</div><div style="font-size: 0.9em; color: rgba(255,255,255,0.7); margin-bottom: 20px;">#${currentPokemon.id.toString().padStart(3, '0')} • ${POKEMON_TYPES[currentPokemon.id]?.join(' / ') || 'Normal'}</div>${berriesHTML}<div id="ball-selector" style="display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; margin-bottom: 15px;">${gameState.inventory.pokeball > 0 ? `<button onclick="startCaptureMinigame('pokeball')" style="background: linear-gradient(135deg, #ef4444, #f97316); padding: 10px 20px; color: white; border: none; border-radius: 8px; cursor: pointer; font-weight: bold;">${getItemIconDisplay('pokeball', '1.2em')} Poké Ball (${gameState.inventory.pokeball})<br><span style="font-size: 0.8em;">${Math.round(calculateCaptureRate('pokeball', currentPokemon.rarity, usingFramby) * 100)}%</span></button>` : ''}${gameState.inventory.greatball > 0 ? `<button onclick="startCaptureMinigame('greatball')" style="background: linear-gradient(135deg, #3b82f6, #2563eb); padding: 10px 20px; color: white; border: none; border-radius: 8px; cursor: pointer; font-weight: bold;">${getItemIconDisplay('greatball', '1.2em')} Super Ball (${gameState.inventory.greatball})<br><span style="font-size: 0.8em;">${Math.round(calculateCaptureRate('greatball', currentPokemon.rarity, usingFramby) * 100)}%</span></button>` : ''}${gameState.inventory.ultraball > 0 ? `<button onclick="startCaptureMinigame('ultraball')" style="background: linear-gradient(135deg, #eab308, #f59e0b); padding: 10px 20px; color: white; border: none; border-radius: 8px; cursor: pointer; font-weight: bold;">${getItemIconDisplay('ultraball', '1.2em')} Hyper Ball (${gameState.inventory.ultraball})<br><span style="font-size: 0.8em;">${Math.round(calculateCaptureRate('ultraball', currentPokemon.rarity, usingFramby) * 100)}%</span></button>` : ''}${gameState.inventory.masterball > 0 ? `<button onclick="startCaptureMinigame('masterball')" style="background: linear-gradient(135deg, #9333ea, #ec4899); padding: 10px 20px; color: white; border: none; border-radius: 8px; cursor: pointer; font-weight: bold;">${getItemIconDisplay('masterball', '1.2em')} Master Ball (${gameState.inventory.masterball})<br><span style="font-size: 0.8em;">100%</span></button>` : ''}${gameState.inventory.diveball > 0 ? `<button onclick="startCaptureMinigame('diveball')" style="background: linear-gradient(135deg, #0ea5e9, #06b6d4); padding: 10px 20px; color: white; border: none; border-radius: 8px; cursor: pointer; font-weight: bold;">${getItemIconDisplay('diveball', '1.2em')} Scuba Ball (${gameState.inventory.diveball})<br><span style="font-size: 0.8em;">${Math.round(calculateCaptureRate('diveball', currentPokemon.rarity, usingFramby) * 100)}%</span></button>` : ''}</div><button onclick="fleePokemon()" class="btn btn--outline" style="padding: 10px 20px; font-size: 1em; background: rgba(239, 68, 68, 0.2); border-color: #ef4444; color: #ef4444;">🏃 Fuir</button></div>`; captureCooldown = Date.now() + 3000; updateCooldownDisplay(); }

// ===== ARCHITECTURE V7.0 GENESIS - SYSTÈME DE FUITE BINAIRE =====
/**
 * Logique centrale de résolution de capture (V7.0)
 * Système binaire : Échec = Fuite immédiate (pas de tentatives multiples)
 * @param {string} ballType - 'pokeball', 'greatball', etc.
 * @param {number} skillBonus - Bonus du skill shot (1.0 à 1.25)
 * @returns {object} Résultat { success: boolean, reason: string, status: 'success'|'retry'|'flee' }
 */
window.attemptCapture = function (ballType, skillBonus = 1.0) {
    if (!currentPokemon) return;

    // Vérification des ressources
    if (gameState.inventory[ballType] <= 0) {
        if (!gameState.system.narrativeFlags.includes('guide_no_balls_shown')) {
            gameState.system.narrativeFlags.push('guide_no_balls_shown');
            setTimeout(() => triggerNarrative('guide_no_balls'), 500);
        }
        const message = window.NARRATIVE_DB?.EVENTS?.FLEE?.[0] || 'Ressources insuffisantes!';
        showToast(message, 'error');
        return;
    }

    const pokemonToCapture = currentPokemon;

    // ===== CONSOMMATION IMMÉDIATE DES RESSOURCES =====
    // Mémorisé avant consommation : permet de savoir si la baie a vraiment été utilisée ce lancer
    const cerizWasAvailable = usingCeriz && gameState.inventory.ceriz > 0;
    gameState.inventory[ballType]--;
    if (usingFramby && gameState.inventory.framby > 0) gameState.inventory.framby--;
    if (usingPinap && gameState.inventory.pinap > 0) gameState.inventory.pinap--;
    if (usingCeriz && gameState.inventory.ceriz > 0) gameState.inventory.ceriz--;

    gameState.totalCaptureAttempts++;

    // ===== CALCUL DE PROBABILITÉ (P) =====
    // Taux de base selon la rareté
    const BASE_RATES = {
        common: 0.70,
        uncommon: 0.50,
        rare: 0.30,
        super_rare: 0.15,
        legendary: 0.05
    };

    let baseRate = BASE_RATES[pokemonToCapture.rarity] || 0.5;

    // Multiplicateurs de Balls
    const BALL_MULTIPLIERS = {
        pokeball: 1.0,
        greatball: 1.5,
        ultraball: 2.0,
        masterball: 1000.0, // Garantit P >= 1.0
        diveball: 1.5
    };

    const ballMult = BALL_MULTIPLIERS[ballType] || 1.0;

    // Multiplicateurs de Baies
    const berryMult = usingFramby ? 1.5 : 1.0;

    // Bonus Buddy
    const buddyId = gameState.buddy?.activeBuddyId;
    const buddy = buddyId ? gameState.buddy.buddies[buddyId] : null;
    const buddyBonus = (buddy && (buddy.level || 1) >= 8) ? 1.10 : 1.0;

    // Calcul final
    let finalProbability = baseRate * ballMult * berryMult * buddyBonus * skillBonus;
    finalProbability = Math.min(finalProbability, 1.0); // Plafonné à 100%

    // Masterball ou Probabilité >= 100%
    if (ballType === 'masterball' || finalProbability >= 1.0) {
        handleCaptureSuccess(pokemonToCapture, ballType, skillBonus);
        return { success: true, method: 'guaranteed' };
    }

    // ===== TIRAGE ALÉATOIRE (R) =====
    const roll = Math.random();
    console.log(`[GENESIS Capture] Proba: ${(finalProbability * 100).toFixed(1)}%, Roll: ${(roll * 100).toFixed(1)}%`);

    // ===== RÉSOLUTION BINAIRE =====
    if (roll <= finalProbability) {
        // SUCCÈS
        handleCaptureSuccess(pokemonToCapture, ballType, skillBonus);
        return { success: true, method: 'luck' };
    } else {
        // ÉCHEC CRITIQUE - Vérification des Safety Nets

        // Safety Net 1: Baie Ceriz — ne se déclenche que si la baie a été consommée ce lancer
        if (cerizWasAvailable) {
            usingCeriz = false; // baie consommée, reset le flag pour éviter des retries infinis
            const message = window.NARRATIVE_DB?.SAFETY_NETS?.CERIZ_BERRY || 'La Baie Ceriz retient le Pokémon!';
            showToast(message, 'info');
            revealPokemon(); // rafraîchit l'UI : retire la case Ceriz, met à jour les compteurs de balls
            return { success: false, status: 'retry', message: message };
        }

        // Safety Net 2: Buddy Protector
        if (checkBuddyProtector && typeof checkBuddyProtector === 'function') {
            if (checkBuddyProtector()) {
                if (typeof consumeBuddyProtector === 'function') {
                    consumeBuddyProtector();
                }
                const message = window.NARRATIVE_DB?.SAFETY_NETS?.BUDDY_PROTECTOR || 'Votre Buddy empêche la fuite!';
                showToast(message, 'info');
                return { success: false, status: 'retry', message: message };
            }
        }

        // Pas de filet de sécurité -> FUITE IMMÉDIATE
        handleCaptureFlee(pokemonToCapture);
        return { success: false, status: 'flee', message: 'Le Pokémon s\'est enfui!' };
    }
};

/**
 * Gère le succès de capture
 */
function handleCaptureSuccess(pokemon, ballType, skillBonus) {
    gameState.totalSuccessfulCaptures++;
    const wasDuplicate = isDuplicate(pokemon.id, pokemon.isShiny);

    // Dialogues narratifs
    if (!wasDuplicate && gameState.totalCaught === 1 && !gameState.system.narrativeFlags.includes('guide_first_capture_shown')) {
        gameState.system.narrativeFlags.push('guide_first_capture_shown');
        setTimeout(() => triggerNarrative('guide_first_capture'), 1500);
    }

    // Ajout à la collection
    addToCollection(pokemon.id, pokemon.isShiny);

    // La stabilisation à 3 captures est gérée par updateSystemStabilityDisplay (appelé via updateUI)

    // Récompenses
    let coinsEarned = (GAME_CONFIG.coinsPerCapture || { common: 55, uncommon: 120, rare: 400, super_rare: 800, legendary: 2500 })[pokemon.rarity];
    if (usingPinap) coinsEarned *= 2;
    const xpGained = gainXP(pokemon.rarity, wasDuplicate);

    gameState.coins += coinsEarned;
    gameState.totalCoinsEarned += coinsEarned;
    gameState.streak++;
    if (gameState.streak > gameState.bestStreak) gameState.bestStreak = gameState.streak;

    // Messages narratifs diégétiques depuis NARRATIVE_DB
    const successMessages = window.NARRATIVE_DB?.EVENTS?.CAPTURE_SUCCESS || ['Signal acquis! Intégrité sauvegardée.'];
    const message = successMessages[Math.floor(Math.random() * successMessages.length)];

    // ===== FIX : Ajouter à l'historique de capture =====
    if (!gameState.captureHistory) gameState.captureHistory = [];
    gameState.captureHistory.unshift({
        id: pokemon.id,
        name: pokemon.name,
        isShiny: pokemon.isShiny,
        rarity: pokemon.rarity,
        status: 'captured',
        time: Date.now()
    });
    if (gameState.captureHistory.length > 10) {
        gameState.captureHistory = gameState.captureHistory.slice(0, 10);
    }
    renderCaptureHistory();

    if (pokemon.isShiny) {
        const shinyMessages = window.NARRATIVE_DB?.EVENTS?.SHINY_DETECTED || ['⚠️ ALERTE : ANOMALIE DÉTECTÉE. Ce code couleur n\'est pas standard!'];
        const shinyMsg = shinyMessages[Math.floor(Math.random() * shinyMessages.length)];
        showToast(`${shinyMsg}\n${pokemon.name} SHINY\n+${coinsEarned} coins\n+${xpGained} XP`, 'success');
        updateQuestProgress('shinies', 1);
    } else if (pokemon.rarity === 'legendary') {
        showCelebration(`👑 LÉGENDAIRE CAPTURÉ! 👑`, `${pokemon.name}\n${message}\n+${coinsEarned} coins\n+${xpGained} XP`, 'legendary');
        updateQuestProgress('legendaries', 1);

        // ===== Dialogue spécial Porygon-Z pour les légendaires =====
        if (!gameState.system.narrativeFlags.includes(`legendary_${pokemon.id}_dialogue_shown`)) {
            gameState.system.narrativeFlags.push(`legendary_${pokemon.id}_dialogue_shown`);
            setTimeout(() => {
                triggerNarrative('legendary_captured');
            }, 2500);
        }
    } else {
        showToast(`${message}\n${pokemon.name}\n+${coinsEarned} coins\n+${xpGained} XP`, 'success');
    }

    // ===== Animation : Le sprite rentre dans une Pokéball =====
    const encounterDiv = document.getElementById('encounter');
    if (encounterDiv) {
        const pokemonSprite = encounterDiv.querySelector('img[src*="pokemon"]');
        if (pokemonSprite) {
            // Créer une Pokéball au centre
            const pokeball = document.createElement('img');
            pokeball.src = `https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/poke-ball.png`;
            pokeball.style.cssText = `
                position: absolute;
                top: 40%;
                left: 50%;
                transform: translate(-50%, -50%);
                width: 80px;
                height: 80px;
                z-index: 1000;
                image-rendering: pixelated;
                opacity: 0;
                transition: opacity 0.2s;
            `;
            encounterDiv.style.position = 'relative';
            encounterDiv.appendChild(pokeball);

            // Animation : le sprite se réduit et rentre dans la Pokéball
            pokemonSprite.style.transition = 'all 0.5s ease-in-out';
            pokemonSprite.style.transform = 'scale(0) translateY(-50px)';
            pokemonSprite.style.opacity = '0';

            // Afficher la Pokéball
            setTimeout(() => {
                pokeball.style.opacity = '1';
                pokeball.style.animation = 'pokeballShake 0.3s ease-in-out 3';
            }, 300);

            // Nettoyer après l'animation
            setTimeout(() => {
                pokeball.remove();
            }, 1200);
        }
    }

    // Effets visuels
    if (window.FX && encounterDiv) {
        FX.shockwave(encounterDiv);
        if (pokemon.isShiny || pokemon.rarity === 'legendary') {
            FX.confetti(window.innerWidth / 2, window.innerHeight / 2, 100);
            FX.stars(window.innerWidth / 2, window.innerHeight / 2, 30);
            FX.screenShake();
        }
    }

    // Nettoyage
    currentPokemon = null;
    usingFramby = false;
    usingPinap = false;
    usingCeriz = false;

    updateQuestProgress('captures', 1);
    updateQuestProgress('coins', coinsEarned);
    updateQuestProgress('streak', gameState.streak);
    if (['rare', 'super_rare', 'legendary'].includes(pokemon.rarity)) {
        updateQuestProgress('rare_captures', 1);
    }

    // ===== ARCHITECTURE V7.0 GENESIS - Mise à jour visuelle de Porygon =====
    if (typeof updatePorygonVisuals === 'function') {
        updatePorygonVisuals();
    }

    saveGame();
    updateUI();
    setTimeout(() => resetEncounterToIdle(), 2000);
}

// Appeler updatePorygonVisuals au chargement et après chaque capture
if (typeof updatePorygonVisuals === 'function') {
    // Appel initial
    setTimeout(() => updatePorygonVisuals(), 1000);

    // Appel après chaque capture (déjà dans handleCaptureSuccess)
    // Appel après level up (à ajouter dans checkLevelUp si elle existe)
}

/**
 * Gère la fuite immédiate (Système Binaire)
 */
function handleCaptureFlee(pokemon) {
    // Messages narratifs diégétiques depuis NARRATIVE_DB
    const fleeMessages = window.NARRATIVE_DB?.EVENTS?.FLEE || ['CONNEXION PERDUE. Le signal s\'est désynchronisé.'];
    const message = fleeMessages[Math.floor(Math.random() * fleeMessages.length)];

    // Afficher en toast uniquement (plus de system-log)
    showToast(`${message}\n${pokemon.name}`, 'error');

    // ===== FIX : Ajouter à l'historique de capture =====
    if (!gameState.captureHistory) gameState.captureHistory = [];
    gameState.captureHistory.unshift({
        id: pokemon.id,
        name: pokemon.name,
        isShiny: pokemon.isShiny,
        rarity: pokemon.rarity,
        status: 'fled',
        time: Date.now()
    });
    if (gameState.captureHistory.length > 10) {
        gameState.captureHistory = gameState.captureHistory.slice(0, 10);
    }
    renderCaptureHistory();

    // Animation de disparition
    const encounterDiv = document.getElementById('encounter');
    if (encounterDiv) {
        encounterDiv.style.transition = 'opacity 0.3s ease-out, transform 0.3s ease-out';
        encounterDiv.style.opacity = '0';
        encounterDiv.style.transform = 'translateX(-100px)';
    }

    // ===== FIX CRITIQUE : Nettoyage IMMÉDIAT de currentPokemon =====
    // Le Pokémon doit disparaître immédiatement, pas après l'animation
    currentPokemon = null;
    usingFramby = false;
    usingPinap = false;
    usingCeriz = false;

    // Statistiques
    gameState.streak = 0;
    gameState.totalFlees++;
    updateQuestProgress('flees', 1);

    saveGame();
    updateUI();

    // Retour à l'idle après animation (plus court pour réactivité)
    setTimeout(() => {
        if (encounterDiv) {
            encounterDiv.style.transition = '';
            encounterDiv.style.opacity = '';
            encounterDiv.style.transform = '';
        }
        // S'assurer que resetEncounterToIdle est appelé
        if (typeof resetEncounterToIdle === 'function') {
            resetEncounterToIdle();
        } else {
            // Fallback : réinitialiser manuellement
            const spawnBtn = document.getElementById('spawn-btn');
            const spawnBtnText = document.getElementById('spawn-btn-text');
            if (spawnBtn) {
                spawnBtn.disabled = false;
                if (spawnBtnText) {
                    spawnBtnText.innerHTML = `${getItemIconDisplay('pokeball', '1.2em')} Capturer un Pokémon`;
                } else {
                    spawnBtn.innerHTML = `${getItemIconDisplay('pokeball', '1.2em')} Capturer un Pokémon`;
                }
            }
        }
    }, 300);
}

window.fleePokemon = function () { if (!currentPokemon) return; showToast(`Vous avez fui ${currentPokemon.name}!`, 'info'); gameState.streak = 0; gameState.totalFlees++; updateQuestProgress('flees', 1); currentPokemon = null; usingFramby = false; usingPinap = false; usingCeriz = false; setTimeout(() => resetEncounterToIdle(), 1500); saveGame(); updateUI(); };

function updateCooldownDisplay() { const btn = document.getElementById('spawn-btn'); if (!btn) return; const btnText = document.getElementById('spawn-btn-text'); if (captureCooldown && captureCooldown > Date.now()) { const remaining = Math.ceil((captureCooldown - Date.now()) / 1000); btn.disabled = true; if (btnText) { btnText.textContent = `Attendez ${remaining}s`; } else { btn.innerHTML = `Attendez ${remaining}s`; } setTimeout(updateCooldownDisplay, 1000); } else { btn.disabled = false; if (btnText) { btnText.innerHTML = `${getItemIconDisplay('pokeball', '1.2em')} Capturer un Pokémon`; } else { btn.innerHTML = `${getItemIconDisplay('pokeball', '1.2em')} Capturer un Pokémon`; } captureCooldown = null; } }

// window.startFishing est défini dans fishing_overhaul.js (version active)

let usingFrambyFishing = false, usingPinapFishing = false, usingCerizFishing = false;
function showFishingEncounter() { if (!currentFishingPokemon) return; const isNew = !gameState.captured.has(currentFishingPokemon.id); const statusBadge = isNew ? '<div style="background: #10b981; color: white; padding: 5px 15px; border-radius: 15px; display: inline-block; margin-bottom: 10px; font-size: 0.9em;">✨ NOUVEAU!</div>' : '<div style="background: #f59e0b; color: white; padding: 5px 15px; border-radius: 15px; display: inline-block; margin-bottom: 10px; font-size: 0.9em;">📖 Doublon</div>'; let berriesHTML = ''; if (gameState.inventory.framby > 0) berriesHTML += `<div style="margin-bottom: 10px;"><label style="color: white; cursor: pointer; background: rgba(255,255,255,0.1); padding: 10px 20px; border-radius: 10px; display: inline-block;"><input type="checkbox" onchange="usingFrambyFishing = this.checked; showFishingEncounter();" ${usingFrambyFishing ? 'checked' : ''} style="margin-right: 8px;">${getItemIconDisplay('framby', '1.2em')} Baie Framby (+50%) [${gameState.inventory.framby}]</label></div>`; if (gameState.inventory.pinap > 0) berriesHTML += `<div style="margin-bottom: 10px;"><label style="color: white; cursor: pointer; background: rgba(255,255,255,0.1); padding: 10px 20px; border-radius: 10px; display: inline-block;"><input type="checkbox" onchange="usingPinapFishing = this.checked; showFishingEncounter();" ${usingPinapFishing ? 'checked' : ''} style="margin-right: 8px;">${getItemIconDisplay('pinap', '1.2em')} Baie Pinap (×2 coins) [${gameState.inventory.pinap}]</label></div>`; if (gameState.inventory.ceriz > 0 && currentFishingPokemon.isShiny) berriesHTML += `<div style="margin-bottom: 10px;"><label style="color: #FFD700; cursor: pointer; background: rgba(255, 215, 0, 0.2); padding: 10px 20px; border-radius: 10px; display: inline-block;"><input type="checkbox" onchange="usingCerizFishing = this.checked; showFishingEncounter();" ${usingCerizFishing ? 'checked' : ''} style="margin-right: 8px;">${getItemIconDisplay('ceriz', '1.2em')} Baie Ceriz (100% SHINY!) [${gameState.inventory.ceriz}]</label></div>`; const modal = document.createElement('div'); modal.className = 'modal active fishing-modal'; modal.style.cssText = 'display: flex !important; position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.9); z-index: 100000; align-items: center; justify-content: center; pointer-events: all;'; modal.innerHTML = `<div class="bg-ocean" style="padding: 30px; border-radius: 20px; max-width: 500px; width: 90%; position: relative; pointer-events: all; z-index: 100001;"><div style="text-align: center;">${statusBadge}<div style="font-size: 2em; margin-bottom: 20px;">🎣 Pokémon Pêché!</div><div style="background: rgba(255,255,255,0.1); padding: 20px; border-radius: 15px; margin-bottom: 15px;"><img src="${getAnimatedSpriteUrl(currentFishingPokemon.id, currentFishingPokemon.isShiny)}" style="width: 150px; height: 150px; image-rendering: pixelated; ${currentFishingPokemon.isShiny ? 'filter: drop-shadow(0 0 20px #FFD700);' : ''}" alt="${currentFishingPokemon.name}"></div><div style="font-size: 1.5em; font-weight: bold; margin: 10px 0; color: ${currentFishingPokemon.isShiny ? '#FFD700' : 'white'};"> ${currentFishingPokemon.isShiny ? '✨ ' : ''}${currentFishingPokemon.name}${currentFishingPokemon.isShiny ? ' ✨' : ''}</div>${berriesHTML}<div style="display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; margin-top: 20px;">${gameState.inventory.pokeball > 0 ? `<button onclick="attemptFishingCapture('pokeball')" style="background: linear-gradient(135deg, #ef4444, #f97316); padding: 10px 20px; color: white; border: none; border-radius: 8px; cursor: pointer; font-weight: bold;">${getItemIconDisplay('pokeball', '1.2em')} Poké Ball (${gameState.inventory.pokeball})<br><span style="font-size: 0.8em;">${Math.round(calculateCaptureRate('pokeball', currentFishingPokemon.rarity, usingFrambyFishing) * 100)}%</span></button>` : ''}${gameState.inventory.greatball > 0 ? `<button onclick="attemptFishingCapture('greatball')" style="background: linear-gradient(135deg, #3b82f6, #2563eb); padding: 10px 20px; color: white; border: none; border-radius: 8px; cursor: pointer; font-weight: bold;">${getItemIconDisplay('greatball', '1.2em')} Super Ball (${gameState.inventory.greatball})<br><span style="font-size: 0.8em;">${Math.round(calculateCaptureRate('greatball', currentFishingPokemon.rarity, usingFrambyFishing) * 100)}%</span></button>` : ''}${gameState.inventory.ultraball > 0 ? `<button onclick="attemptFishingCapture('ultraball')" style="background: linear-gradient(135deg, #eab308, #f59e0b); padding: 10px 20px; color: white; border: none; border-radius: 8px; cursor: pointer; font-weight: bold;">${getItemIconDisplay('ultraball', '1.2em')} Hyper Ball (${gameState.inventory.ultraball})<br><span style="font-size: 0.8em;">${Math.round(calculateCaptureRate('ultraball', currentFishingPokemon.rarity, usingFrambyFishing) * 100)}%</span></button>` : ''}${gameState.inventory.masterball > 0 ? `<button onclick="attemptFishingCapture('masterball')" style="background: linear-gradient(135deg, #9333ea, #ec4899); padding: 10px 20px; color: white; border: none; border-radius: 8px; cursor: pointer; font-weight: bold;">${getItemIconDisplay('masterball', '1.2em')} Master Ball (${gameState.inventory.masterball})<br><span style="font-size: 0.8em;">100%</span></button>` : ''}${gameState.inventory.diveball > 0 ? `<button onclick="attemptFishingCapture('diveball')" style="background: linear-gradient(135deg, #0ea5e9, #06b6d4); padding: 10px 20px; color: white; border: none; border-radius: 8px; cursor: pointer; font-weight: bold;">${getItemIconDisplay('diveball', '1.2em')} Scuba Ball (${gameState.inventory.diveball})<br><span style="font-size: 0.8em;">${Math.round(calculateCaptureRate('diveball', currentFishingPokemon.rarity, usingFrambyFishing) * 100)}%</span></button>` : ''}</div><button onclick="fleeFishingEncounter()" class="btn btn--outline btn--full-width" style="margin-top: 15px; background: rgba(239, 68, 68, 0.2); border-color: #ef4444; color: #ef4444;">🏃 Fuir (ne pas capturer)</button></div></div>`; document.body.appendChild(modal); }
window.fleeFishingEncounter = function () { const fishingModal = document.querySelector('.fishing-modal'); if (fishingModal) { fishingModal.style.animation = 'slideOutRight 0.4s ease-out'; setTimeout(() => { if (fishingModal.parentNode) fishingModal.remove(); }, 400); } showToast('Vous avez laissé le Pokémon s\'échapper.', 'info'); if (currentFishingPokemon) { gameState.fishingHistory.unshift({ id: currentFishingPokemon.id, name: currentFishingPokemon.name, isShiny: currentFishingPokemon.isShiny, rarity: currentFishingPokemon.rarity, status: 'fled', time: Date.now() }); if (gameState.fishingHistory.length > 10) gameState.fishingHistory = gameState.fishingHistory.slice(0, 10); renderFishingHistory(); } currentFishingPokemon = null; saveGame(); updateUI(); };

window.attemptFishingCapture = function (ballType) {
    if (!currentFishingPokemon) return; if (gameState.inventory[ballType] <= 0) { showToast('Vous n\'avez plus de cette Pokéball!', 'error'); return; } gameState.inventory[ballType]--; if (usingFrambyFishing && gameState.inventory.framby > 0) gameState.inventory.framby--; if (usingPinapFishing && gameState.inventory.pinap > 0) gameState.inventory.pinap--; if (usingCerizFishing && gameState.inventory.ceriz > 0) gameState.inventory.ceriz--; const captureRate = calculateCaptureRate(ballType, currentFishingPokemon.rarity, usingFrambyFishing); const success = ballType === 'masterball' ? true : Math.random() < captureRate; const fishingModals = document.querySelectorAll('.fishing-modal'); fishingModals.forEach(modal => { modal.style.animation = 'slideOutRight 0.4s ease-out'; setTimeout(() => { if (modal.parentNode) modal.remove(); }, 400); }); const allModals = document.querySelectorAll('.modal.active'); allModals.forEach(modal => { if (modal.classList.contains('fishing-modal')) { modal.style.animation = 'slideOutRight 0.4s ease-out'; setTimeout(() => { if (modal.parentNode) modal.remove(); }, 400); } }); if (success) {
        gameState.totalFished++; updateQuestProgress('fished', 1); const wasDuplicate = isDuplicate(currentFishingPokemon.id, currentFishingPokemon.isShiny); addToCollection(currentFishingPokemon.id, currentFishingPokemon.isShiny);
        // ===== MURMURE D'ENTROPIE pour la pêche =====
        if (typeof triggerAmbientNarrative === 'function') {
            triggerAmbientNarrative('fishing_success', { pokemon: currentFishingPokemon.name });
        }
        let coinsEarned = (GAME_CONFIG.coinsPerCapture || { common: 55, uncommon: 120, rare: 400, super_rare: 800, legendary: 2500 })[currentFishingPokemon.rarity]; if (usingPinapFishing) coinsEarned *= 2; gameState.coins += coinsEarned; gameState.totalCoinsEarned += coinsEarned; updateQuestProgress('coins', coinsEarned); const xpGained = gainXP(currentFishingPokemon.rarity, wasDuplicate); const fishingModal = document.querySelector('.fishing-modal'); if (window.FX && fishingModal) { FX.shockwave(fishingModal); if (currentFishingPokemon.isShiny || currentFishingPokemon.rarity === 'legendary') { FX.confetti(window.innerWidth / 2, window.innerHeight / 2, 100); FX.stars(window.innerWidth / 2, window.innerHeight / 2, 30); FX.screenShake(); } } if (currentFishingPokemon.isShiny && !wasDuplicate) { showToast(`✨ ${currentFishingPokemon.name} SHINY pêché!\n+${coinsEarned} coins\n+${xpGained} XP`, 'success'); updateQuestProgress('shinies', 1); } else { showToast(`✅ ${currentFishingPokemon.name} pêché!\n+${coinsEarned} coins\n+${xpGained} XP${wasDuplicate ? ' (doublon)' : ''}`, 'success'); } if (['rare', 'super_rare', 'legendary'].includes(currentFishingPokemon.rarity)) { updateQuestProgress('rare_captures', 1); } if (currentFishingPokemon.rarity === 'legendary') { updateQuestProgress('legendaries', 1); } gameState.fishingHistory.unshift({ id: currentFishingPokemon.id, name: currentFishingPokemon.name, isShiny: currentFishingPokemon.isShiny, rarity: currentFishingPokemon.rarity, status: 'captured', time: Date.now() }); if (gameState.fishingHistory.length > 10) gameState.fishingHistory = gameState.fishingHistory.slice(0, 10); renderFishingHistory();
    } else { showToast(`❌ ${currentFishingPokemon.name} s'est échappé!`, 'error'); gameState.fishingHistory.unshift({ id: currentFishingPokemon.id, name: currentFishingPokemon.name, isShiny: currentFishingPokemon.isShiny, rarity: currentFishingPokemon.rarity, status: 'fled', time: Date.now() }); if (gameState.fishingHistory.length > 10) gameState.fishingHistory = gameState.fishingHistory.slice(0, 10); renderFishingHistory(); } currentFishingPokemon = null; usingFrambyFishing = false; usingPinapFishing = false; usingCerizFishing = false; saveGame(); updateUI();
};

window.switchPokedexMode = function (mode) { if (mode === 'gallery') mode = 'grid'; document.getElementById('pokemon-grid').style.display = mode === 'grid' ? 'grid' : 'none'; document.getElementById('pokemon-list').style.display = mode === 'list' ? 'block' : 'none'; gameState.pokedexMode = mode; const btnGrid = document.getElementById('mode-grid-btn'); const btnList = document.getElementById('mode-list-btn');[btnGrid, btnList].forEach(btn => { if (btn) { btn.classList.remove('btn--primary'); btn.classList.add('btn--outline'); } }); if (mode === 'grid' && btnGrid) { btnGrid.classList.add('btn--primary'); btnGrid.classList.remove('btn--outline'); renderPokedexGrid(); } else if (mode === 'list' && btnList) { btnList.classList.add('btn--primary'); btnList.classList.remove('btn--outline'); renderPokedexList(); } saveGame(); };
window.switchPokedexRegion = function (region) { if (!gameState.pokedexRegion) gameState.pokedexRegion = 'Kanto'; const regionRanges = { Kanto: { min: 1, max: 151 }, Johto: { min: 152, max: 251 }, Hoenn: { min: 252, max: 386 } }; const hasPokemonInRegion = Array.from(gameState.captured).some(id => id >= regionRanges[region].min && id <= regionRanges[region].max); const isUnlocked = gameState.unlockedRegions && gameState.unlockedRegions.has(region); if (region !== 'Kanto' && !hasPokemonInRegion && !isUnlocked) { showToast(`🔒 Région ${region} verrouillée!\nObtenez un Pokémon de cette région pour la débloquer.`, 'error'); return; } gameState.pokedexRegion = region; const regionTabKanto = document.getElementById('region-tab-kanto'); const regionTabJohto = document.getElementById('region-tab-johto'); const regionTabHoenn = document.getElementById('region-tab-hoenn'); const hasJohtoPokemon = Array.from(gameState.captured).some(id => id >= 152 && id <= 251); const hasHoennPokemon = Array.from(gameState.captured).some(id => id >= 252 && id <= 386); const isJohtoUnlocked = gameState.unlockedRegions && gameState.unlockedRegions.has('Johto'); const isHoennUnlocked = gameState.unlockedRegions && gameState.unlockedRegions.has('Hoenn');[regionTabKanto, regionTabJohto, regionTabHoenn].forEach(btn => { if (btn) { btn.classList.remove('btn--primary'); btn.classList.remove('btn--outline'); btn.style.opacity = ''; btn.style.filter = ''; } }); if (region === 'Kanto' && regionTabKanto) { regionTabKanto.classList.add('btn--primary'); regionTabKanto.classList.remove('btn--outline'); regionTabKanto.innerHTML = '🌋 Kanto'; } if (regionTabJohto) { if (isJohtoUnlocked || hasJohtoPokemon) { regionTabJohto.classList.add(region === 'Johto' ? 'btn--primary' : 'btn--outline'); if (region === 'Johto') regionTabJohto.classList.remove('btn--outline'); regionTabJohto.innerHTML = (isJohtoUnlocked ? '' : '🔒 ') + '🏔️ Johto'; regionTabJohto.style.opacity = '1'; regionTabJohto.style.filter = 'none'; } else { regionTabJohto.classList.add('btn--outline'); regionTabJohto.style.opacity = '0.5'; regionTabJohto.style.filter = 'grayscale(100%)'; regionTabJohto.innerHTML = '🔒 🏔️ Johto'; } } if (regionTabHoenn) { if (isHoennUnlocked || hasHoennPokemon) { regionTabHoenn.classList.add(region === 'Hoenn' ? 'btn--primary' : 'btn--outline'); if (region === 'Hoenn') regionTabHoenn.classList.remove('btn--outline'); regionTabHoenn.innerHTML = (isHoennUnlocked ? '' : '🔒 ') + '🌊 Hoenn'; regionTabHoenn.style.opacity = '1'; regionTabHoenn.style.filter = 'none'; } else { regionTabHoenn.classList.add('btn--outline'); regionTabHoenn.style.opacity = '0.5'; regionTabHoenn.style.filter = 'grayscale(100%)'; regionTabHoenn.innerHTML = '🔒 🌊 Hoenn'; } } const currentRegionDisplay = document.getElementById('current-region-display'); const regionProgressDisplay = document.getElementById('region-progress-display'); if (currentRegionDisplay) currentRegionDisplay.textContent = region; const range = regionRanges[region]; const capturedCount = Array.from(gameState.captured).filter(id => id >= range.min && id <= range.max).length; const total = range.max - range.min + 1; if (regionProgressDisplay) regionProgressDisplay.textContent = `${capturedCount}/${total}`; if (gameState.pokedexMode === 'grid') renderPokedexGrid(); else if (gameState.pokedexMode === 'list') renderPokedexList(); saveGame(); };

function renderPokedexGrid() {
    const grid = document.getElementById('pokemon-grid');
    if (!grid) return;
    grid.innerHTML = ''; // Reset propre

    const region = gameState.pokedexRegion || 'Kanto';
    const regionRanges = { Kanto: { min: 1, max: 151 }, Johto: { min: 152, max: 251 }, Hoenn: { min: 252, max: 386 } };
    const range = regionRanges[region] || regionRanges.Kanto;
    const isUnlocked = gameState.unlockedRegions && gameState.unlockedRegions.has(region);
    const filters = gameState.pokedexFilters || { status: 'all', rarity: 'all', type: 'all', evolvable: 'all' };
    const pokemonIdsToShow = isUnlocked ? Array.from({ length: range.max - range.min + 1 }, (_, i) => range.min + i) : Array.from(gameState.captured).filter(id => id >= range.min && id <= range.max);

    // Création d'un Fragment pour n'écrire dans le DOM qu'une seule fois (Gain perf énorme)
    const fragment = document.createDocumentFragment();
    const placeholder = "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 96 96'%3E%3Ccircle cx='48' cy='48' r='10' fill='%23333' opacity='0.1'/%3E%3C/svg%3E";

    pokemonIdsToShow.forEach(id => {
        const hasCaught = gameState.captured.has(id);
        const hasShiny = gameState.shinies.has(id);
        const name = FRENCH_NAMES[id] || `Pokémon #${id}`;
        const rarity = getRarity(id);
        const types = POKEMON_TYPES[id] || [];

        if (filters.status === 'caught' && !hasCaught) return;
        if (filters.status === 'not-caught' && hasCaught) return;
        if (filters.status === 'shiny' && !hasShiny) return;
        if (filters.rarity !== 'all' && rarity !== filters.rarity) return;
        if (filters.type !== 'all' && !types.includes(filters.type)) return;
        if (filters.evolvable === 'evolvable') {
            const hasEvolved = gameState.evolved.has(id);
            if (hasEvolved) return;
            const evolvedByLevel = EVOLUTION_BY_LEVEL[id];
            if (evolvedByLevel && gameState.captured.has(evolvedByLevel)) return;
            const evolvedByStone = EVOLUTION_DATA[id] ? Object.values(EVOLUTION_DATA[id]) : [];
            if (evolvedByStone.length > 0 && evolvedByStone.some(evolvedId => gameState.captured.has(evolvedId))) return;
            const canEvolveByCaptures = evolvedByLevel && (gameState.capturedCount[id] || 0) >= 5;
            const canEvolveByStone = EVOLUTION_DATA[id] && Object.keys(EVOLUTION_DATA[id]).some(stone => gameState.inventory[stone] > 0);
            if (!canEvolveByCaptures && !canEvolveByStone) return;
        }

        const rarityColors = { common: '#9ca3af', uncommon: '#10b981', rare: '#3b82f6', super_rare: '#8b5cf6', legendary: '#f59e0b' };
        const card = document.createElement('div');
        card.className = 'pokemon-card';
        if (hasCaught && hasShiny) {
            card.classList.add('pokemon-card-shiny-complete', 'shiny-card-effect');
        }

        let cardStyle = `background: var(--dark-surface); border: 2px solid ${hasCaught ? rarityColors[rarity] : 'var(--dark-border)'}; border-radius: 12px; padding: 12px; text-align: center; cursor: ${hasCaught ? 'pointer' : 'default'}; transition: all 0.3s; position: relative;`;
        if (hasCaught && hasShiny) {
            cardStyle += `background: linear-gradient(135deg, rgba(255, 215, 0, 0.15), rgba(147, 51, 234, 0.15), rgba(236, 72, 153, 0.15)); border: 3px solid transparent; background-clip: padding-box; box-shadow: 0 0 20px rgba(255, 215, 0, 0.4), 0 0 40px rgba(147, 51, 234, 0.2), inset 0 0 30px rgba(255, 215, 0, 0.1); animation: shinyCardPulse 3s ease-in-out infinite;`;
        }
        card.style.cssText = cardStyle;

        if (hasCaught) {
            card.addEventListener('click', () => showPokemonDetail(id));
            card.addEventListener('mouseenter', function () { this.style.transform = hasCaught && hasShiny ? 'translateY(-8px) scale(1.05)' : 'translateY(-5px)'; });
            card.addEventListener('mouseleave', function () { this.style.transform = 'translateY(0) scale(1)'; });
        }

        // OPTIMISATION : Lazy Loading natif + Placeholder SVG ultra-léger
        // Afficher l'image Shiny si possédé
        const realSrc = hasCaught ? (hasShiny ? `https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/shiny/${id}.png` : `https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${id}.png`) : placeholder;

        card.innerHTML = `
            <div style="position: relative; margin: 0 auto 8px; width: 96px; height: 96px; display: flex; align-items: center; justify-content: center;">
                <img src="${placeholder}" data-src="${realSrc}" class="lazy-sprite" width="96" height="96" style="object-fit: contain; image-rendering: pixelated; display: block; margin: 0 auto; ${hasCaught && hasShiny ? 'filter: drop-shadow(0 0 10px rgba(255, 215, 0, 0.6)) drop-shadow(0 0 20px rgba(147, 51, 234, 0.4)) brightness(1.1); animation: shinyImageFloat 4s ease-in-out infinite;' : ''};" alt="${hasCaught ? name : '???'}">
                ${hasShiny ? `<div class="shiny-indicator">✨</div>` : `<div class="shiny-shadow">✨</div>`}
            </div>
            <div style="font-weight: bold; font-size: 11px; color: var(--text-secondary); margin-bottom: 4px;">#${id.toString().padStart(3, '0')}</div>
            <div class="name" style="font-size: 13px; font-weight: 600;">${hasCaught ? name : '???'}</div>
        `;

        fragment.appendChild(card);
    });

    grid.appendChild(fragment);
    initLazyLoader(); // Lancer l'observateur
}

// Fonction utilitaire pour le lazy loading
function initLazyLoader() {
    if (window.lazyLoaderObserver) {
        window.lazyLoaderObserver.disconnect();
    }

    window.lazyLoaderObserver = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                const img = entry.target;
                if (img.dataset.src) {
                    img.src = img.dataset.src;
                    img.removeAttribute('data-src');
                    window.lazyLoaderObserver.unobserve(img);
                }
            }
        });
    }, { rootMargin: '50px' });

    document.querySelectorAll('.lazy-sprite[data-src]').forEach(img => window.lazyLoaderObserver.observe(img));
}

function renderPokedexList() { const list = document.getElementById('pokemon-list'); if (!list) return; list.innerHTML = ''; const region = gameState.pokedexRegion || 'Kanto'; const regionRanges = { Kanto: { min: 1, max: 151 }, Johto: { min: 152, max: 251 }, Hoenn: { min: 252, max: 386 } }; const range = regionRanges[region] || regionRanges.Kanto; const isUnlocked = gameState.unlockedRegions && gameState.unlockedRegions.has(region); const hasPokemonInRegion = Array.from(gameState.captured).some(id => id >= range.min && id <= range.max); if (!isUnlocked && region !== 'Kanto' && !hasPokemonInRegion) { list.innerHTML = '<p style="text-align: center; color: var(--text-secondary); padding: 20px;">🔒 Région verrouillée - Aucun Pokémon à afficher</p>'; return; } const filters = gameState.pokedexFilters || { status: 'all', rarity: 'all', type: 'all', evolvable: 'all' }; const pokemonIdsToShow = isUnlocked ? Array.from({ length: range.max - range.min + 1 }, (_, i) => range.min + i) : Array.from(gameState.captured).filter(id => id >= range.min && id <= range.max); for (const id of pokemonIdsToShow) { const hasCaught = gameState.captured.has(id); const hasShiny = gameState.shinies.has(id); const name = FRENCH_NAMES[id] || `Pokémon #${id}`; const types = POKEMON_TYPES[id] || []; const rarity = getRarity(id); if (filters.status === 'caught' && !hasCaught) continue; if (filters.status === 'not-caught' && hasCaught) continue; if (filters.status === 'shiny' && !hasShiny) continue; if (filters.rarity !== 'all' && rarity !== filters.rarity) continue; if (filters.type !== 'all' && !types.includes(filters.type)) continue; if (filters.evolvable === 'evolvable') { const hasEvolved = gameState.evolved.has(id); if (hasEvolved) continue; const evolvedByLevel = EVOLUTION_BY_LEVEL[id]; if (evolvedByLevel && gameState.captured.has(evolvedByLevel)) continue; const evolvedByStone = EVOLUTION_DATA[id] ? Object.values(EVOLUTION_DATA[id]) : []; if (evolvedByStone.length > 0 && evolvedByStone.some(evolvedId => gameState.captured.has(evolvedId))) continue; const canEvolveByCaptures = evolvedByLevel && (gameState.capturedCount[id] || 0) >= 5; const canEvolveByStone = EVOLUTION_DATA[id] && Object.keys(EVOLUTION_DATA[id]).some(stone => gameState.inventory[stone] > 0); if (!canEvolveByCaptures && !canEvolveByStone) continue; } const rarityNames = { common: 'Commun', uncommon: 'Peu Commun', rare: 'Rare', super_rare: 'Super Rare', legendary: 'Légendaire' }; const rarityColors = { common: '#9ca3af', uncommon: '#10b981', rare: '#3b82f6', super_rare: '#8b5cf6', legendary: '#f59e0b' }; const item = document.createElement('div'); item.style.cssText = `background: var(--dark-elevated); padding: 12px; border-radius: 8px; margin-bottom: 8px; display: flex; align-items: center; gap: 12px; cursor: ${hasCaught ? 'pointer' : 'default'};`; if (hasCaught) item.addEventListener('click', () => showPokemonDetail(id)); item.innerHTML = `<img src="https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${id}.png" style="width: 50px; height: 50px; image-rendering: pixelated; object-fit: contain; object-position: center; display: block;"><div style="flex: 1;"><div style="font-weight: bold; color: white;">#${id.toString().padStart(3, '0')} ${hasCaught ? name : '???'}</div><div style="font-size: 0.9em; color: var(--text-secondary);">${types.join(' / ') || 'Normal'}</div></div><div style="text-align: right;"><span style="color: ${rarityColors[rarity]}; font-weight: bold; font-size: 0.9em;">${rarityNames[rarity]}</span>${hasShiny ? '<div style="color: #FFD700; font-size: 1em;">✨</div>' : ''}</div>`; list.appendChild(item); } }


window.showPokemonGalleryDetail = function (pokemonId) { const name = FRENCH_NAMES[pokemonId]; const hasShiny = gameState.shinies.has(pokemonId); const types = POKEMON_TYPES[pokemonId] || []; const rarity = getRarity(pokemonId); const count = gameState.capturedCount[pokemonId] || 1; const lore = POKEMON_LORE[pokemonId] || `${name} est un Pokémon fascinant avec ses propres caractéristiques uniques.`; const taille = POKEMON_SIZES[pokemonId] || 'Taille inconnue'; const rarityColors = { common: '#9ca3af', uncommon: '#10b981', rare: '#3b82f6', super_rare: '#8b5cf6', legendary: '#f59e0b' }; const rarityNames = { common: 'Commun', uncommon: 'Peu Commun', rare: 'Rare', super_rare: 'Super Rare', legendary: 'Légendaire' }; let evolutionHTML = ''; const evolutionData = EVOLUTION_DATA[pokemonId]; const evolvedForm = EVOLUTION_BY_LEVEL[pokemonId]; const hasEvolvedForm = evolvedForm && gameState.captured.has(evolvedForm); const canEvolveAtAll = evolvedForm || evolutionData; if (!canEvolveAtAll) { evolutionHTML = '<div style="background: rgba(100,100,100,0.2); padding: 15px; border-radius: 10px; margin: 20px 0; text-align: center; color: rgba(255,255,255,0.6); font-style: italic;">Ce Pokémon ne peut pas évoluer</div>'; } else if (hasEvolvedForm) { evolutionHTML = '<div style="background: rgba(0,255,0,0.2); padding: 15px; border-radius: 10px; margin: 20px 0; text-align: center; color: white; font-weight: bold;">✅ Déjà évolué en ' + FRENCH_NAMES[evolvedForm] + '</div>'; } else { if (evolvedForm) { const duplicateCount = count; const canEvolve = duplicateCount >= 5; evolutionHTML += `<div style="background: rgba(0,0,0,0.3); padding: 15px; border-radius: 10px; margin: 20px 0;"><div style="color: white; font-weight: bold; margin-bottom: 10px;">🔄 Évolution par captures</div><div style="background: rgba(0,0,0,0.3); border-radius: 8px; overflow: hidden; height: 12px; margin-bottom: 10px;"><div style="height: 100%; background: linear-gradient(90deg, #4ade80, #22c55e); width: ${Math.min((duplicateCount / 5) * 100, 100)}%; transition: width 0.5s;"></div></div><div style="color: rgba(255,255,255,0.8); font-size: 0.9em;">${duplicateCount}/5 captures</div>${canEvolve ? `<button onclick="evolveByCaptures(${pokemonId})" class="btn btn--primary" style="margin-top: 10px; width: 100%;">⭐ Évoluer</button>` : ''}</div>`; } if (evolutionData) { evolutionHTML += '<div style="background: rgba(0,0,0,0.3); padding: 15px; border-radius: 10px; margin: 20px 0;"><div style="color: white; font-weight: bold; margin-bottom: 10px;">💎 Évolutions par Pierre</div>'; if (evolutionData.fire_stone && gameState.inventory.fire_stone > 0) evolutionHTML += `<button onclick="evolvePokemon(${pokemonId},'fire_stone')" class="btn btn--primary" style="margin: 5px; width: calc(100% - 10px);">🔥 Pierre Feu</button>`; if (evolutionData.water_stone && gameState.inventory.water_stone > 0) evolutionHTML += `<button onclick="evolvePokemon(${pokemonId},'water_stone')" class="btn btn--primary" style="margin: 5px; width: calc(100% - 10px);">💧 Pierre Eau</button>`; if (evolutionData.thunder_stone && gameState.inventory.thunder_stone > 0) evolutionHTML += `<button onclick="evolvePokemon(${pokemonId},'thunder_stone')" class="btn btn--primary" style="margin: 5px; width: calc(100% - 10px);">⚡ Pierre Foudre</button>`; if (evolutionData.moon_stone && gameState.inventory.moon_stone > 0) evolutionHTML += `<button onclick="evolvePokemon(${pokemonId},'moon_stone')" class="btn btn--primary" style="margin: 5px; width: calc(100% - 10px);">🌙 Pierre Lune</button>`; if (evolutionData.leaf_stone && gameState.inventory.leaf_stone > 0) evolutionHTML += `<button onclick="evolvePokemon(${pokemonId},'leaf_stone')" class="btn btn--primary" style="margin: 5px; width: calc(100% - 10px);">🍃 Pierre Plante</button>`; evolutionHTML += '</div>'; } } const modal = document.createElement('div'); modal.className = 'modal active'; modal.style.cssText = 'display: flex !important; position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.95); z-index: 10000; align-items: center; justify-content: center; overflow-y: auto; padding: 20px;'; modal.innerHTML = `<div style="background: linear-gradient(135deg, #667eea, #764ba2); padding: 40px; border-radius: 20px; max-width: 600px; width: 100%; position: relative;"><button onclick="this.closest('.modal').remove()" style="position: absolute; top: 15px; right: 15px; background: rgba(255,255,255,0.2); border: none; color: white; font-size: 24px; cursor: pointer; width: 35px; height: 35px; border-radius: 50%;">×</button><h1 style="color: white; text-align: center; margin: 0 0 15px 0;">#${pokemonId.toString().padStart(3, '0')} ${name}</h1><div style="text-align: center; margin-bottom: 20px;"><span style="display: inline-block; background: ${rarityColors[rarity]}; color: white; padding: 8px 20px; border-radius: 20px; font-weight: bold;">${rarityNames[rarity]}</span></div><div style="display: flex; gap: 15px; margin-bottom: 20px; justify-content: center; flex-wrap: wrap;">${types.map(type => `<span style="background: rgba(255,255,255,0.2); color: white; padding: 10px 20px; border-radius: 15px; font-weight: bold;">${type}</span>`).join('')}</div><div style="display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-bottom: 20px;"><div style="text-align: center;"><div style="color: rgba(255,255,255,0.8); font-size: 0.95em; margin-bottom: 10px; font-weight: bold;">Version Normale</div><img src="${getAnimatedSpriteUrl(pokemonId, false)}" style="width: 200px; height: 200px; background: rgba(255,255,255,0.1); border-radius: 15px; border: 2px solid rgba(255,255,255,0.3); image-rendering: pixelated; padding: 10px; object-fit: contain; object-position: center;"></div><div style="text-align: center;"><div style="color: ${hasShiny ? '#FFD700' : 'rgba(255,255,255,0.5)'}; font-size: 0.95em; margin-bottom: 10px; font-weight: bold;">Version Shiny ${hasShiny ? '✨' : '(Non obtenue)'}</div><img src="${getAnimatedSpriteUrl(pokemonId, true)}" style="width: 200px; height: 200px; background: rgba(255,255,255,0.1); border-radius: 15px; border: 2px solid ${hasShiny ? '#FFD700' : 'rgba(255,255,255,0.2)'}; image-rendering: pixelated; padding: 10px; opacity: ${hasShiny ? '1' : '0.4'};filter: ${hasShiny ? '' : 'grayscale(1)'}; object-fit: contain; object-position: center;"></div></div><div style="background: rgba(0,0,0,0.3); padding: 20px; border-radius: 15px; text-align: left; color: white; margin-bottom: 20px;"><div style="margin-bottom: 12px;"><strong>📏 Taille:</strong> ${taille}</div><div style="margin-bottom: 12px;"><strong>📚 Lore:</strong> ${lore}</div><div style="margin-bottom: 8px;"><strong>🎯 Capturé ${count} fois</strong></div>${hasShiny ? '<div style="color: #FFD700; font-weight: bold;">✨ Shiny Possédé</div>' : ''}</div>${evolutionHTML}</div>`; document.body.appendChild(modal); modal.addEventListener('click', (e) => { if (e.target === modal) modal.remove(); }); };

window.showPokemonDetail = function (pokemonId) { const hasCaught = gameState.captured.has(pokemonId); if (!hasCaught) { showToast('Pokémon pas encore capturé!', 'error'); return; } showPokemonGalleryDetail(pokemonId); };

// ===== PART 3: QUÊTES, BLIND BOX, SHOP, INVENTAIRE, UI =====

window.renderAllQuests = function () { renderDailyQuests(); renderSpecialQuests(); renderPermanentQuests(); };

function getParisDate() { const now = new Date(); const parisTimeStr = now.toLocaleString('en-US', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }); const [datePart, timePart] = parisTimeStr.split(', '); const [month, day, year] = datePart.split('/'); const [hours, minutes, seconds] = timePart.split(':'); return new Date(year, month - 1, day, hours, minutes, seconds); }
function getParisDateString() { const parisDate = getParisDate(); return `${parisDate.getFullYear()}-${String(parisDate.getMonth() + 1).padStart(2, '0')}-${String(parisDate.getDate()).padStart(2, '0')}`; }
function generateDailyQuests() { if (!gameState.questsProgress.daily) { gameState.questsProgress.daily = {}; } if (!gameState.claimedQuests.daily) { gameState.claimedQuests.daily = new Set(); } if (!gameState.dailyQuestCompletionDates) { gameState.dailyQuestCompletionDates = {}; } const parisDate = getParisDate(); const parisDateStr = getParisDateString(); const lastResetDate = gameState.lastDailyQuestDate; if (lastResetDate === parisDateStr && QUESTS_DATA.daily && QUESTS_DATA.daily.length > 0) return; const yesterdayDate = new Date(parisDate); yesterdayDate.setDate(yesterdayDate.getDate() - 1); const yesterdayStr = `${yesterdayDate.getFullYear()}-${String(yesterdayDate.getMonth() + 1).padStart(2, '0')}-${String(yesterdayDate.getDate()).padStart(2, '0')}`; const completedYesterday = []; for (const questId in gameState.dailyQuestCompletionDates) { const completionDate = gameState.dailyQuestCompletionDates[questId]; if (completionDate === yesterdayStr) { completedYesterday.push(questId); } } if (lastResetDate !== parisDateStr) { for (const questId in gameState.questsProgress.daily) { if (!gameState.claimedQuests.daily.has(questId)) { delete gameState.questsProgress.daily[questId]; } } QUESTS_DATA.daily = []; gameState.claimedQuests.daily.clear(); } if (!QUESTS_DATA.daily || QUESTS_DATA.daily.length === 0) { const selectedQuests = []; for (const poolName of ['easy', 'medium', 'hard', 'expert']) { const pool = DAILY_QUEST_POOLS[poolName]; if (pool && pool.length > 0) { const availableQuests = pool.filter(q => !completedYesterday.includes(q.id)); const questPool = availableQuests.length > 0 ? availableQuests : pool; const randomQuest = questPool[Math.floor(Math.random() * questPool.length)]; selectedQuests.push({ ...randomQuest, pool: poolName }); } } QUESTS_DATA.daily = selectedQuests; gameState.lastDailyQuestDate = parisDateStr; gameState.lastDailyQuestReset = Date.now(); if (lastResetDate !== parisDateStr) { gameState.dailyQuestStreak++; if (gameState.dailyQuestStreak > 0 && gameState.dailyQuestStreak % 7 === 0) { showToast(`🔥 Streak de ${gameState.dailyQuestStreak} jours ! Bonus récompenses !`, 'success'); } } saveGame(); } }
function renderDailyQuests() {
    generateDailyQuests();
    const container = document.getElementById('daily-quests-container');
    if (!container) return;
    container.innerHTML = '';
    if (!QUESTS_DATA.daily || QUESTS_DATA.daily.length === 0) {
        container.innerHTML = '<p style="text-align: center; color: var(--text-secondary); padding: 20px;">Aucune quête quotidienne disponible pour le moment.</p>';
        return;
    }
    if (!gameState.questsProgress.daily) { gameState.questsProgress.daily = {}; }
    if (!gameState.claimedQuests.daily) { gameState.claimedQuests.daily = new Set(); }
    const quests = [...QUESTS_DATA.daily].sort((a, b) => {
        const aClaimed = gameState.claimedQuests.daily.has(a.id);
        const bClaimed = gameState.claimedQuests.daily.has(b.id);
        if (aClaimed && !bClaimed) return 1;
        if (!aClaimed && bClaimed) return -1;
        const poolOrder = { easy: 1, medium: 2, hard: 3, expert: 4 };
        return (poolOrder[a.pool] || 0) - (poolOrder[b.pool] || 0);
    });
    for (const quest of quests) {
        if (!quest || !quest.id) continue;
        const progress = gameState.questsProgress.daily[quest.id] || 0;
        const isClaimed = gameState.claimedQuests.daily.has(quest.id);
        const isCompleted = progress >= quest.target;

        // GÉNÉRATION DYNAMIQUE DES RÉCOMPENSES
        let rewardText = `+${quest.reward.coins}💰`;
        if (quest.reward.xp) rewardText += ` · +${quest.reward.xp} XP`;
        for (const [key, value] of Object.entries(quest.reward)) {
            if (key !== 'coins' && key !== 'xp' && key !== 'badge') {
                const itemData = ALL_ITEMS[key];
                if (itemData) {
                    rewardText += ` · ${value}× ${getItemIconDisplay(key, '16px')}`;
                }
            }
        }

        const poolColors = { easy: '#10b981', medium: '#3b82f6', hard: '#f59e0b', expert: '#ec4899' };
        const poolNames = { easy: 'Facile', medium: 'Moyen', hard: 'Difficile', expert: 'Expert' };
        const poolColor = poolColors[quest.pool] || '#666';
        const poolName = poolNames[quest.pool] || '';
        const card = document.createElement('div');
        card.style.cssText = `background: ${isClaimed ? 'rgba(16, 185, 129, 0.15)' : 'var(--dark-elevated)'}; padding: 15px; border-radius: 12px; margin-bottom: 10px; border-left: 4px solid ${isClaimed ? '#10b981' : isCompleted ? poolColor : '#666'}; opacity: ${isClaimed ? '0.5' : '1'}; filter: ${isClaimed ? 'grayscale(50%)' : 'none'};`;
        card.innerHTML = `<div style="display: flex; gap: 15px; align-items: flex-start;"><div style="font-size: 2em;">${quest.icon || '⚾'}</div><div style="flex: 1;"><div style="display: flex; align-items: center; gap: 10px; margin-bottom: 5px;"><div style="font-weight: bold; color: white;">${isClaimed ? '✔ ' : isCompleted ? '🎉 ' : ''}${quest.name || 'Quête'}</div><span style="background: ${poolColor}; color: white; padding: 2px 8px; border-radius: 10px; font-size: 0.75em; font-weight: bold;">${poolName}</span></div><div style="font-size: 0.9em; color: var(--text-secondary); margin-bottom: 10px;">${quest.desc || ''}</div><div style="background: rgba(0,0,0,0.2); border-radius: 8px; overflow: hidden; height: 8px;"><div style="height: 100%; background: ${poolColor}; width: ${Math.min((progress / (quest.target || 1)) * 100, 100)}%;"></div></div><div style="font-size: 0.85em; color: #bbb; margin-top: 5px;">${progress} / ${quest.target || 1}</div></div><div style="text-align: right;">${isClaimed ? `<div style="color: #4ade80; font-weight: bold;">✔ Réclamée</div>` : isCompleted ? `<button class="claim-quest-btn btn btn--primary" data-quest-type="daily" data-quest-id="${quest.id}" style="padding: 8px 16px;">Réclamer</button>` : `<div style="color: #999;"></div>`}<div style="font-size: 0.9em; color: #FFD700; margin-top: 10px;">${rewardText}</div></div></div>`;
        container.appendChild(card);
    }
    container.querySelectorAll('.claim-quest-btn').forEach(btn => {
        btn.addEventListener('click', function () {
            const questType = this.getAttribute('data-quest-type');
            const questId = this.getAttribute('data-quest-id');
            if (window.claimQuest) { window.claimQuest(questType, questId); }
        });
    });
}
