window.evolvePokemon = function (pokemonId, stoneType) { if (!gameState.captured.has(pokemonId)) { showToast('Vous devez d\'abord capturer ce Pokémon!', 'error'); return; } const evolutionData = EVOLUTION_DATA[pokemonId]; if (!evolutionData || !evolutionData[stoneType]) { showToast('Ce Pokémon ne peut pas évoluer avec cette pierre!', 'error'); return; } if ((gameState.inventory[stoneType] || 0) <= 0) { showToast(`Vous n'avez pas de ${ALL_ITEMS[stoneType]?.name || stoneType}!`, 'error'); return; } const evolvedId = evolutionData[stoneType]; gameState.inventory[stoneType]--; gameState.captured.add(evolvedId); gameState.evolved.add(evolvedId); if (!gameState.capturedCount[evolvedId]) gameState.capturedCount[evolvedId] = 0; gameState.capturedCount[evolvedId]++; gameState.totalCaught++; const evolvedName = FRENCH_NAMES[evolvedId]; showCelebration(`✨ ÉVOLUTION! ✨`, `${FRENCH_NAMES[pokemonId]} → ${evolvedName}`, 'achievement', evolvedId); saveGame(); updateUI(); if (document.getElementById('pokedex-page')?.classList.contains('active')) renderPokedexGrid(); if (document.querySelector('.modal.active')) document.querySelector('.modal.active').remove(); };
window.evolveByCaptures = function (pokemonId) { if (!gameState.captured.has(pokemonId)) { showToast('Vous devez d\'abord capturer ce Pokémon!', 'error'); return; } const count = gameState.capturedCount[pokemonId] || 0; if (count < 5) { showToast(`Vous devez capturer ce Pokémon 5 fois! (${count}/5)`, 'error'); return; } const evolvedId = EVOLUTION_BY_LEVEL[pokemonId]; if (!evolvedId) { showToast('Ce Pokémon ne peut pas évoluer par captures!', 'error'); return; } const evolveModal = document.createElement('div'); evolveModal.style.cssText = 'position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.95); display: flex; align-items: center; justify-content: center; z-index: 99999;'; evolveModal.innerHTML = `<div style="text-align: center;"><img src="${getAnimatedSpriteUrl(pokemonId, false)}" id="evolve-sprite" style="width: 200px; height: 200px; image-rendering: pixelated; animation: evolutionPulse 0.5s infinite; object-fit: contain; object-position: center;"></div>`; document.body.appendChild(evolveModal); let frame = 0; const spriteEl = document.getElementById('evolve-sprite'); const evolveInterval = setInterval(() => { frame++; if (frame <= 10) { spriteEl.src = `https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${pokemonId}.png`; } else if (frame <= 20) { spriteEl.src = `https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${evolvedId}.png`; } else { clearInterval(evolveInterval); } }, 200); setTimeout(() => { clearInterval(evolveInterval); evolveModal.remove(); gameState.captured.add(evolvedId); gameState.evolved.add(evolvedId); if (!gameState.capturedCount[evolvedId]) gameState.capturedCount[evolvedId] = 0; gameState.capturedCount[evolvedId]++; gameState.totalCaught++; const evolvedName = FRENCH_NAMES[evolvedId]; showCelebration(`✨ ÉVOLUTION! ✨`, `${FRENCH_NAMES[pokemonId]} → ${evolvedName}`, 'achievement', evolvedId); saveGame(); updateUI(); if (document.getElementById('pokedex-page')?.classList.contains('active')) renderPokedexGrid(); if (document.querySelector('.modal.active')) document.querySelector('.modal.active').remove(); }, 4500); };
