window.porygonInteraction = function () {
    console.log('🤖 Porygon clicked!');
    const container = document.getElementById('porygon-avatar-container');
    const sprite = document.getElementById('porygon-intro-sprite');

    // Feedback visuel (Wiggle)
    if (container) {
        container.classList.remove('porygon-click-feedback');
        void container.offsetWidth; // Trigger reflow
        container.classList.add('porygon-click-feedback');
    }

    // Coeur flottant
    const heart = document.createElement('div');
    heart.className = 'porygon-heart';
    heart.innerHTML = '❤️';
    if (container) container.appendChild(heart);
    setTimeout(() => heart.remove(), 1000);

    // Son
    if (window.playSound) window.playSound('click');

    // Dialogue aléatoire
    const phrases = [
        "Système stable. Merci, utilisateur.",
        "Analyse de vos données... Intéressant.",
        "Je détecte une grande ambition chez vous.",
        "N'oubliez pas d'hydrater votre processeur biologique.",
        "Les données sont l'essence de l'univers.",
        "bip bip... chargement de l'affection... 100%",
        "Vous êtes mon dresseur favori (techniquement le seul).",
        "Attention aux glitchs dans le secteur 7G.",
        "Mes capteurs indiquent une chance de Shiny augmentée... ou pas.",
        "J'aime quand vous cliquez sur moi.",
        "Optimisation des câlins numériques...",
        "Voulez-vous jouer au Poker plus tard ?",
        "MissingNo me fait peur parfois...",
        "Vos progrès sont enregistrés dans le cloud.",
        "Le Professeur Chen serait fier.",
        "Une erreur est survenue : Trop de mignonnerie.",
        "Calcul de la trajectoire de la prochaine Pokéball...",
        "Avez-vous essayé d'éteindre et de rallumer ?",
        "Je rêve de moutons électriques.",
        "❤️"
    ];

    const randomPhrase = phrases[Math.floor(Math.random() * phrases.length)];

    const dialogBox = document.getElementById('porygon-text');
    if (dialogBox) {
        dialogBox.innerText = randomPhrase;
        dialogBox.style.opacity = '1';
    } else {
        if (window.showAmbientWhisper) {
            window.showAmbientWhisper(randomPhrase);
        } else {
            window.showFloatingText(randomPhrase, window.innerWidth / 2, window.innerHeight / 3, '#00ff9d');
        }
    }

    // Petit bonus gameplay
    if (Math.random() < 0.05) {
        if (window.addCoins) {
            window.addCoins(10);
            window.showFloatingText("+10 Coins (Donnée corrompue)", window.innerWidth / 2, window.innerHeight / 2 + 50, "#FFD700");
        }
    }
};

// ==========================================
// DAILY REWARDS INITIALIZATION
// ==========================================
document.addEventListener('DOMContentLoaded', () => {
    // Initialiser le système de Daily Rewards (si le script est chargé)
    if (window.DailyLoginSystem) {
        console.log('📅 Initialisation Daily Rewards via EventListener...');
        window.dailyLoginSystem = new DailyLoginSystem();

        // Petit délai pour laisser le reste charger
        setTimeout(() => {
            // Vérifier si le joueur a dépassé l'intro (par exemple si username est set)
            const username = localStorage.getItem('poke_username');
            if (username && window.dailyLoginSystem.checkLogin()) {
                window.dailyLoginSystem.showRewardModal();
            }
        }, 1500);
    }

    // ==========================================
    // PWA INTRO INITIALIZATION FIX
    // ==========================================
    // Vérifier si l'intro doit être affichée (nouvelle partie ou PWA)
    setTimeout(() => {
        const savedData = localStorage.getItem('poke_gamedata');
        const gameBoyScreen = document.getElementById('game-boy-screen');

        // Si pas de sauvegarde ou si introSeen n'est pas dans gameState
        if (gameBoyScreen && (!savedData || !gameState.introSeen)) {
            console.log('🎮 PWA: Affichage de l\'écran d\'intro');
            gameBoyScreen.style.display = 'flex';
        } else if (gameBoyScreen) {
            // Sinon s'assurer que l'intro est cachée
            gameBoyScreen.style.display = 'none';
        }
    }, 500);
});
